verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..fe3a207 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,59 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Adversarial substitution: a trusted observation that names a different model than
+// the profile requested must fail everywhere, even behind a cryptographically verified
+// receipt, and it must never launder telemetry it never carried into known facts.
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+const substituted = Object.freeze({ model: claude.model, trusted: true });
+assert.deepEqual(profiles.evaluateModelProof(local, substituted), {
+  requested_model: local.model,
+  observed_model: claude.model,
+  status: 'failed',
+  reason_code: 'MODEL_OBSERVATION_MISMATCH',
+});
+const substitutedState = profiles.missionControlExecutorState({
+  profile: local, observation: substituted, wrapper, verification,
+});
+assert.equal(substitutedState.receipt_status, 'verified', 'a verified receipt must not vouch for the model');
+assert.equal(substitutedState.model_status, 'failed');
+assert.equal(substitutedState.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedState.requested_model, local.model, 'the requested model must survive substitution');
+assert.equal(substitutedState.observed_model, claude.model);
+for (const [value, status] of [
+  [substitutedState.cost, substitutedState.cost_status],
+  [substitutedState.duration_ms, substitutedState.duration_status],
+  [substitutedState.tokens, substitutedState.tokens_status],
+]) {
+  assert.equal(value, null);
+  assert.equal(status, 'unknown', 'telemetry absent from the observation must stay unknown');
+}
+const substitutedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substituted, wrapper, verification,
+});
+assert.equal(substitutedReplay.model_status, 'failed');
+assert.equal(substitutedReplay.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedReplay.requested_model, local.model);
+assert.equal(substitutedReplay.observed_model, claude.model);
+assert.deepEqual(
+  [substitutedReplay.cost_status, substitutedReplay.duration_status, substitutedReplay.tokens_status],
+  ['unknown', 'unknown', 'unknown'],
+);
+
+// "Unknown" must track what is actually missing, not blanket every substituted run:
+// telemetry the trusted observation does carry is still reported as known.
+const partialState = profiles.missionControlExecutorState({
+  profile: local,
+  observation: { ...substituted, duration_ms: 1200, tokens: 8192 },
+  wrapper,
+  verification,
+});
+assert.equal(partialState.model_status, 'failed');
+assert.equal(partialState.duration_ms, 1200);
+assert.equal(partialState.duration_status, 'known');
+assert.equal(partialState.tokens, 8192);
+assert.equal(partialState.tokens_status, 'known');
+assert.equal(partialState.cost, null);
+assert.equal(partialState.cost_status, 'unknown');
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
